import sys
from collections import defaultdict

def canonicalize(hostname):
    parts = hostname.split('.')
    while len(parts) > 1 and parts[-1] == '':
        parts.pop()
    return '.'.join(parts)

def canonicalize_path(path):
    parts = path.split('/')
    while len(parts) > 1 and parts[-1] == '':
        parts.pop()
    return '/'.join(parts)

def main():
    input = sys.stdin.read
    data = input().splitlines()
    n = int(data[0])
    addresses = data[1:]

    canonicalized_hosts = defaultdict(list)
    for address in addresses:
        parts = address.split('/')
        hostname = canonicalize(parts[2])
        path = canonicalize_path(parts[3] if len(parts) > 3 else '')
        canonicalized_hosts[(hostname, path)].append(address)

    groups = [set(values) for values in canonicalized_hosts.values() if len(values) > 1]
    unique_groups = []
    for group in groups:
        if all(len(group.intersection(other)) == len(group) for other in unique_groups):
            unique_groups.append(group)

    print(len(unique_groups))
    for group in unique_groups:
        print(' '.join(sorted(group)))

if __name__ == "__main__":
